import org.junit.jupiter.api.io.TempDir;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.Arguments;
import org.junit.jupiter.params.provider.MethodSource;

class LmdbLegacyNoOpMarkerRegressionTest {
	private static final byte[] MARKER_KEY = { 0 };
	private static final byte[] HISTORICAL_MARKER = { 1 };

	@ParameterizedTest
	@MethodSource("keyStates")
	void uppercaseLegacyOwnerPreservesOrRepairsItsPhysicalKeys(KeyState state, boolean hashed,
			@TempDir(cleanup = CleanupMode.NEVER) Path directory) throws Exception {
		LmdbCompatibilityFixtures.extract("v2-610-default.zip", directory);
		var vf = SimpleValueFactory.getInstance();
		IRI subject = vf.createIRI("urn:legacy-noop:subject");
		IRI predicate = vf.createIRI("urn:legacy-noop:predicate");
		Literal literal = vf.createLiteral(hashed ? "an intentionally longer physical owner payload" : "w", "EN");
		LmdbStoreConfig config = new LmdbStoreConfig().setInlineLiterals(false).setForceSync(true);
		long id;
		LmdbStore first = new LmdbStore(directory.toFile(), config);
		SailRepository seed = new SailRepository(first);
		try {
			seed.init();
			try (var connection = seed.getConnection()) {
				connection.add(subject, predicate, literal);
			}
			id = ((ValueStore) first.getValueFactory()).getId(literal);
		} finally {
			seed.shutDown();
		}
		byte[] idKey = LmdbCompatibilityFixtures.idKey(id);
		byte[] raw = LmdbCompatibilityFixtures.nativeGet(directory, null, idKey);
		assertNotNull(raw);
		byte[] canonical = ValueStoreRecordCodec.canonicalLanguageKey(raw);
		assertFalse(Arrays.equals(raw, canonical), "the fixture must retain an uppercase physical language spelling");
		assertEquals(hashed, raw.length > ValueStoreRecordCodec.MAX_INLINE_KEY_BYTES);
		byte[] rawKey = reverseKey(raw);
		byte[] canonicalKey = reverseKey(canonical);
		assertFalse(Arrays.equals(rawKey, canonicalKey), "raw and canonical keys must be distinct");
		assertArrayEquals(idKey, LmdbCompatibilityFixtures.nativeGet(directory, null, rawKey));
		assertNull(LmdbCompatibilityFixtures.nativeGet(directory, null, canonicalKey));
		if (state != KeyState.RAW_ONLY) {
			LmdbCompatibilityFixtures.nativePut(directory, null, canonicalKey, idKey);
			if (state == KeyState.CANONICAL_ONLY) {
				LmdbCompatibilityFixtures.nativePut(directory, null, rawKey, null);
			}
		}
		LmdbCompatibilityFixtures.nativePut(directory, "ref_counts", MARKER_KEY, HISTORICAL_MARKER);
		LmdbStore reopened = new LmdbStore(directory.toFile(), config);
		SailRepository repository = new SailRepository(reopened);
		try {
			repository.init();
			ValueStore values = (ValueStore) reopened.getValueFactory();
			assertFalse(values.hasTrustedReferenceCounts());
			assertEquals(id, values.getId(literal), "normalization must keep the live owner identity");
			try (var connection = repository.getConnection()) {
				assertTrue(connection.hasStatement(subject, predicate, literal, false));
				assertTrue(connection.hasStatement(subject, predicate, vf.createLiteral(literal.getLabel(), "en"), false));
			}
		} finally {
			repository.shutDown();
		}
		assertArrayEquals(idKey, LmdbCompatibilityFixtures.nativeGet(directory, null, rawKey),
				"the original legacy physical owner must remain available to older readers");
		assertNull(LmdbCompatibilityFixtures.nativeGet(directory, null, canonicalKey),
				"legacy normalization removes a separate canonical alias");
		if (state == KeyState.RAW_ONLY) {
			assertArrayEquals(HISTORICAL_MARKER, LmdbCompatibilityFixtures.nativeGet(directory, "ref_counts", MARKER_KEY),
					"a truly unchanged owner graph must preserve the earlier reader's marker");
		} else {
			assertNull(LmdbCompatibilityFixtures.nativeGet(directory, "ref_counts", MARKER_KEY),
					"an owner-key repair must fence the earlier reader's marker before it commits");
		}
	}

	private static byte[] reverseKey(byte[] data) {
		return data.length <= ValueStoreRecordCodec.MAX_INLINE_KEY_BYTES ? data
				: ValueStoreRecordCodec.hashKey(ValueStoreRecordCodec.hash(data));
	}

	private static Stream<Arguments> keyStates() {
		return Arrays.stream(KeyState.values())
				.flatMap(state -> Stream.of(Arguments.of(state, false), Arguments.of(state, true)));
	}

	private enum KeyState {
		RAW_ONLY, CANONICAL_ONLY, DUAL_KEY
	}
}
